import sys, json, random, collections
sys.path.insert(0, "/app/tmp/t")
from run import run_json
import ref

def rhex(rng, n=None):
    if n is None: n = rng.randint(0, 6)
    return "".join(rng.choice("0123456789abcdef") for _ in range(2 * n))

def mkf(rng):
    r = rng.random()
    if r < 0.05: return {"type": "PADDING"}
    if r < 0.08: return {"type": "PING"}
    if r < 0.55:
        sid = rng.choice([0, 0, 0, 2, 2, 4, 6, 8, 10])
        return {"type": "STREAM", "id": sid, "offset": rng.randint(0, 14),
                "data_hex": rhex(rng), "fin": rng.random() < 0.25}
    if r < 0.72:
        return {"type": "RESET_STREAM", "id": rng.choice([0, 2, 4, 6]),
                "final_size": rng.randint(0, 16)}
    if r < 0.82:
        return {"type": "STOP_SENDING", "id": rng.choice([0, 4, 8])}
    if r < 0.92:
        return {"type": "CRYPTO", "offset": rng.randint(0, 14), "data_hex": rhex(rng)}
    if r < 0.97:
        return {"type": "ACK", "ranges": [[0, rng.randint(0, 9)]]}
    return {"type": "CLOSE", "app": rng.random() < 0.5, "code": rng.randint(0, 50)}

def mkcfg(rng):
    return {"early": rng.random() < 0.5,
            "overlap": rng.choice(["reject", "first"]),
            "buffer_packets": rng.randint(1, 8),
            "idle_ms": 0,
            "max_streams_bidi": rng.randint(1, 5),
            "max_streams_uni": rng.randint(1, 5),
            "max_stream_data": rng.randint(6, 24),
            "max_data": rng.randint(10, 80),
            "crypto_limit": rng.randint(6, 24),
            "sent": {"I": [[0, 9]], "H": [[0, 9]], "A": [[0, 9]]}}

def mktrace(rng, tid):
    cfg = mkcfg(rng)
    events = [{"t": 0, "op": "key", "level": "A", "action": "install"}]
    t = 0
    pn = 0
    for _ in range(rng.randint(2, 16)):
        t += rng.choice([0, 1, 2, 4])
        r = rng.random()
        if r < 0.06:
            events.append({"t": t, "op": "key", "level": rng.choice(["I", "H", "Z", "A"]),
                           "action": rng.choice(["install", "discard"])})
        else:
            k = rng.randint(1, 3)
            pkts = []
            for _ in range(k):
                pkts.append({"level": rng.choice(["A", "A", "A", "Z", "I", "H"]),
                             "pn": pn if rng.random() < 0.8 else max(0, pn - 2),
                             "auth": rng.random() < 0.97,
                             "frames": [mkf(rng) for _ in range(rng.randint(1, 5))]})
                pn += 1
            # A packets must be last: sort so that A/Z... only A matters; put A at end
            pkts.sort(key=lambda p: (p["level"] == "A",))
            events.append({"t": t, "op": "datagram", "bytes": 1200, "packets": pkts})
    return {"id": tid, "config": cfg, "events": events}

stats = collections.Counter()
seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 90000
n = int(sys.argv[2]) if len(sys.argv) > 2 else 400
bad = 0
for i in range(n):
    rng = random.Random(seed0 + i)
    doc = {"version": 1, "traces": [mktrace(rng, "t%d" % k) for k in range(rng.randint(1, 3))]}
    rc, out, err = run_json(doc)
    if rc != 0:
        print("RC!=0", seed0 + i, err[:300]); bad += 1; continue
    got = json.loads(out); want = ref.run(doc)
    if got != want:
        bad += 1
        print("MISMATCH seed", seed0 + i)
        print("input:", json.dumps(doc))
        for g, w in zip(got["results"], want["results"]):
            if g != w:
                print(" got:", json.dumps(g)[:1500])
                print(" want:", json.dumps(w)[:1500])
        if bad >= 2: break
    for tr in got["results"]:
        stats["state:" + tr["connection"]["state"]] += 1
        stats["code:" + str(tr["connection"]["code"])] += 1
        stats["rt"] += 1
        for s in tr["streams"]:
            stats["stream"] += 1
            if s["reset"]: stats["stream:reset"] += 1
            if s["final_size"] is not None: stats["stream:fin"] += 1
            if s["delivered_hex"]: stats["stream:delivered"] += 1
        for c in tr["crypto"]:
            if c["highest"]: stats["crypto:" + c["level"]] += 1
            if c["contiguous_hex"]: stats["crypto:contig"] += 1
        for p in tr["packets"]:
            stats["p:" + p["status"] + "/" + p["reason"]] += 1
print("mismatches:", bad, "of", n)
for k, v in sorted(stats.items()): print("  %-40s %d" % (k, v))
PYEOF
